import java.io.*;
import java.util.*;

public class Main {
	static final long MOD = 998244353L;

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);

		int N = sc.ni();
		long K = sc.nl();
		if (K >= N) {
			pw.println(0);
			pw.close();
			return;
		}
		int C = (int)(N - K);

		long[] fac = new long[200001];
		fac[0] = 1L;
		for (int i = 1; i <= 200000; i++)
			fac[i] = (i * fac[i-1]) % MOD;

		long ans = 0L;
		int sign = (C % 2 == 0) ? 1 : -1; // sign for i = C is (-1)^(C-C)=1, but we start from i=C, so sign=1 always. Actually original sign=1 for i=C. So keep sign=1.
		sign = 1;
		// Use while with post-decrement
		int i = C;
		while (i > 0) {
			long val = (choose(C, i, fac) * power(i, N, MOD)) % MOD;
			ans = (ans + sign * val) % MOD;
			if (ans < 0) ans += MOD;
			sign = -sign;
			i--;
		}

		long mult = (C == N) ? 1L : (2L * choose(N, C, fac)) % MOD;
		pw.println((ans * mult) % MOD);

		pw.close();
	}

	public static long choose(int n, int k, long[] fac) {
		long den = (fac[k] * fac[n-k]) % MOD;
		long denInv = power(den, MOD - 2, MOD);
		return (fac[n] * denInv) % MOD;
	}

	public static long power(long x, long y, long m) {
		if (y < 0) return 0L;
		long ans = 1L;
		x %= m;
		while (y > 0) {
			if ((y & 1) == 1)
				ans = (ans * x) % m;
			y >>= 1;
			x = (x * x) % m;
		}
		return ans;
	}

	static class FastScanner {
		BufferedReader br;
		StringTokenizer st;

		public FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int ni() { return Integer.parseInt(next()); }

		long nl() { return Long.parseLong(next()); }

		double nd() { return Double.parseDouble(next()); }

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return str;
		}
	}
}
